import {
  afterRenderEffect,
  booleanAttribute,
  ChangeDetectionStrategy,
  Component,
  computed,
  ElementRef,
  forwardRef,
  inject,
  input,
  linkedSignal,
  model,
  signal,
} from "@angular/core";
import { type ControlValueAccessor, NG_VALUE_ACCESSOR } from "@angular/forms";
import { NgIcon } from "@ng-icons/core";
import { lucideChevronRight } from "@ng-icons/lucide";
import { KoInput } from "@/ui/primitives/input.directive";
import { KoSwitch } from "@/ui/primitives/switch.component";
import { cn } from "@/ui/utils";

let nextId = 0;

/**
 * Label above the control, unit in the label, hint or error below. The first control inside is
 * marked invalid and pointed at the message, so the error is more than red text.
 */
@Component({
  selector: "ko-field",
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { "[attr.title]": "null", class: "contents" },
  template: `
    <!-- The label wraps whatever control is projected, so it is associated with it. -->
    <!-- eslint-disable-next-line @angular-eslint/template/label-has-associated-control -->
    <label [class]="classes()">
      <span class="text-xs font-medium text-muted-foreground">{{ label() }}</span>
      <ng-content />
      @if (error()) {
        <span [id]="messageId" role="alert" class="text-xs text-danger-fg">{{ error() }}</span>
      } @else if (hint()) {
        <span [id]="messageId" class="text-xs text-muted-foreground">{{ hint() }}</span>
      }
    </label>
  `,
})
export class KoField {
  readonly label = input.required<string>();
  readonly hint = input<string>();
  readonly error = input<string>();
  readonly class = input<string>("");

  protected readonly messageId = `ko-field-message-${nextId++}`;
  protected readonly classes = computed(() => cn("grid content-start gap-1.5", this.class()));

  private readonly host = inject<ElementRef<HTMLElement>>(ElementRef).nativeElement;
  private original: { invalid: string | null; describedBy: string | null } | undefined;

  constructor() {
    afterRenderEffect(() => {
      const error = this.error();
      const message = error || this.hint();
      const control = this.host.querySelector<HTMLElement>("input, textarea, select, button");
      if (!control) return;
      this.original ??= {
        invalid: control.getAttribute("aria-invalid"),
        describedBy: control.getAttribute("aria-describedby"),
      };
      const invalid = error ? "true" : this.original.invalid;
      const describedBy = message ? this.messageId : this.original.describedBy;
      if (invalid === null) control.removeAttribute("aria-invalid");
      else control.setAttribute("aria-invalid", invalid);
      if (describedBy === null) control.removeAttribute("aria-describedby");
      else control.setAttribute("aria-describedby", describedBy);
    });
  }
}

/**
 * Whole-number input. Keeps the typed text while it is being edited so the field can be emptied
 * and retyped, and reports a number only when the text is one. Works with `formControl`/`ngModel`.
 */
@Component({
  selector: "ko-number-input",
  imports: [KoInput],
  changeDetection: ChangeDetectionStrategy.OnPush,
  providers: [
    { provide: NG_VALUE_ACCESSOR, useExisting: forwardRef(() => KoNumberInput), multi: true },
  ],
  host: { class: "contents", "[attr.aria-label]": "null" },
  template: `
    <input
      koInput
      inputmode="numeric"
      [class]="inputClasses()"
      [value]="text()"
      [disabled]="inactive()"
      [attr.aria-label]="ariaLabel() ?? null"
      (input)="onInput($event)"
      (blur)="onBlur()"
    />
  `,
})
export class KoNumberInput implements ControlValueAccessor {
  readonly min = input<number>();
  readonly max = input<number>();
  readonly disabled = input(false, { transform: booleanAttribute });
  readonly ariaLabel = input<string | undefined>(undefined, { alias: "aria-label" });
  readonly class = input<string>("");

  private readonly value = signal(0);
  protected readonly text = signal("0");
  private readonly formDisabled = signal(false);
  protected readonly inactive = computed(() => this.disabled() || this.formDisabled());
  protected readonly inputClasses = computed(() => cn("tabular-nums", this.class()));

  private onChange: (value: number) => void = () => undefined;
  private onTouched: () => void = () => undefined;

  writeValue(value: number | null): void {
    const next = value ?? this.min() ?? 0;
    this.value.set(next);
    const current = this.text();
    this.text.set(Number(current) === next && current !== "" ? current : String(next));
  }
  registerOnChange(fn: (value: number) => void): void {
    this.onChange = fn;
  }
  registerOnTouched(fn: () => void): void {
    this.onTouched = fn;
  }
  setDisabledState(isDisabled: boolean): void {
    this.formDisabled.set(isDisabled);
  }

  private clamp(value: number): number {
    return Math.min(this.max() ?? Infinity, Math.max(this.min() ?? 0, value));
  }

  private commit(next: number): void {
    if (next === this.value()) return;
    this.value.set(next);
    this.onChange(next);
  }

  protected onInput(event: Event): void {
    const field = event.target as HTMLInputElement;
    const text = field.value.replace(/[^\d]/g, "");
    const max = this.max();
    // The input keeps what the browser put in it unless told otherwise, so write the text back.
    if (field.value !== text) field.value = text;
    this.text.set(text);
    // The typed text stays as typed so it can be edited; the value reported is already in range
    // above, and blur puts the text in line with it.
    if (text !== "") this.commit(max == null ? Number(text) : Math.min(Number(text), max));
  }

  protected onBlur(): void {
    const text = this.text();
    const parsed = this.clamp(text === "" ? (this.min() ?? 0) : Number(text));
    this.text.set(String(parsed));
    this.commit(parsed);
    this.onTouched();
  }
}

/** A switch with its label and description beside it. */
@Component({
  selector: "ko-switch-field",
  imports: [KoSwitch],
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { "[attr.title]": "null", class: "flex items-start gap-3" },
  template: `
    <ko-switch
      class="mt-0.5"
      [id]="id"
      [aria-label]="label()"
      [disabled]="disabled()"
      [(checked)]="checked"
    />
    <label [for]="id" class="grid cursor-pointer gap-0.5">
      <span class="text-sm">{{ label() }}</span>
      @if (description()) {
        <span class="text-xs text-muted-foreground">{{ description() }}</span>
      }
    </label>
  `,
})
export class KoSwitchField {
  readonly checked = model(false);
  readonly label = input.required<string>();
  readonly description = input<string>();
  readonly disabled = input(false, { transform: booleanAttribute });

  protected readonly id = `ko-switch-field-${nextId++}`;
}

/** Advanced fields sit behind this, closed by default. */
@Component({
  selector: "ko-disclosure",
  imports: [NgIcon],
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { "[attr.title]": "null", class: "block rounded-lg shadow-[var(--shadow-border)]" },
  template: `
    <button
      type="button"
      class="flex w-full items-center gap-2 px-3 py-2.5 text-left text-xs font-medium text-muted-foreground hover:text-foreground"
      [attr.aria-expanded]="open()"
      (click)="chosen.set(!open())"
    >
      <ng-icon
        aria-hidden="true"
        size="0.875rem"
        class="transition-transform"
        [class.rotate-90]="open()"
        [svg]="chevron"
      />
      {{ title() }}
    </button>
    @if (open()) {
      <div class="grid gap-4 border-t border-border px-3 py-4">
        <ng-content />
      </div>
    }
  `,
})
export class KoDisclosure {
  readonly title = input.required<string>();
  readonly defaultOpen = input(false, { transform: booleanAttribute });
  /** Keeps it open while a field inside has an error to show. */
  readonly forceOpen = input(false, { transform: booleanAttribute });

  protected readonly chevron = lucideChevronRight;
  protected readonly chosen = linkedSignal(() => this.defaultOpen());
  protected readonly open = computed(() => this.chosen() || this.forceOpen());
}

export type ChoiceCardOption<T extends string = string> = {
  id: T;
  label: string;
  description: string;
  /** An `@ng-icons/lucide` SVG string. */
  icon: string;
};

/** A choice between a few options drawn as cards, for the first step of the create flow. */
@Component({
  selector: "ko-choice-cards",
  imports: [NgIcon],
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { role: "radiogroup", class: "grid gap-2 sm:grid-cols-2" },
  template: `
    @for (option of options(); track option.id) {
      <button
        type="button"
        role="radio"
        [attr.aria-checked]="option.id === value()"
        [class]="cardClasses(option.id === value())"
        (click)="value.set(option.id)"
      >
        <span
          class="grid size-8 shrink-0 place-items-center rounded-md bg-inset text-muted-foreground shadow-[var(--shadow-border)]"
        >
          <ng-icon aria-hidden="true" size="1rem" [svg]="option.icon" />
        </span>
        <span class="grid gap-0.5">
          <span class="text-sm font-medium">{{ option.label }}</span>
          <span class="text-xs text-muted-foreground">{{ option.description }}</span>
        </span>
      </button>
    }
  `,
})
export class KoChoiceCards<T extends string = string> {
  readonly value = model.required<T>();
  readonly options = input.required<readonly ChoiceCardOption<T>[]>();

  protected cardClasses(active: boolean): string {
    return cn(
      "flex items-start gap-3 rounded-lg px-3 py-3 text-left transition-[background-color,box-shadow]",
      active
        ? "bg-secondary shadow-[var(--shadow-border-hover)]"
        : "shadow-[var(--shadow-border)] hover:bg-secondary/50",
    );
  }
}

import {
  ChangeDetectionStrategy,
  Component,
  provideZonelessChangeDetection,
  signal,
} from "@angular/core";
import { TestBed, type ComponentFixture } from "@angular/core/testing";
import { FormControl, ReactiveFormsModule } from "@angular/forms";
import { KoDisclosure, KoField, KoNumberInput } from "@/ui/form.component";
import { KoInput } from "@/ui/primitives/input.directive";

@Component({
  selector: "ko-form-host",
  imports: [KoField, KoNumberInput, KoDisclosure, KoInput, ReactiveFormsModule],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <ko-field label="Workers" [error]="error()" hint="How many.">
      <ko-number-input [formControl]="workers" [min]="1" [max]="16" aria-label="Workers" />
    </ko-field>
    <ko-field label="Name" hint="What it is called.">
      <input koInput id="name" />
    </ko-field>
    <ko-disclosure title="Advanced" [forceOpen]="force()">
      <p id="advanced">Inside</p>
    </ko-disclosure>
  `,
})
class HostComponent {
  readonly workers = new FormControl(4, { nonNullable: true });
  readonly error = signal<string | undefined>(undefined);
  readonly force = signal(false);
}

describe("form composites", () => {
  let fixture: ComponentFixture<HostComponent>;
  let host: HostComponent;
  const root = () => fixture.nativeElement as HTMLElement;
  const input = () => root().querySelector<HTMLInputElement>('input[aria-label="Workers"]')!;
  const settle = async () => {
    fixture.detectChanges();
    await fixture.whenStable();
  };
  const type = (text: string) => {
    input().value = text;
    input().dispatchEvent(new Event("input"));
  };

  beforeEach(async () => {
    TestBed.configureTestingModule({ providers: [provideZonelessChangeDetection()] });
    fixture = TestBed.createComponent(HostComponent);
    host = fixture.componentInstance;
    await settle();
  });

  describe("KoNumberInput", () => {
    it("names the inner input from an aria-label attribute, not the host", () => {
      expect(input().getAttribute("aria-label")).toBe("Workers");
      expect(root().querySelector("ko-number-input")!.hasAttribute("aria-label")).toBe(false);
    });

    it("shows the value and reports typed numbers", async () => {
      expect(input().value).toBe("4");
      type("9");
      await settle();
      expect(host.workers.value).toBe(9);
    });

    it("reports a value above max as max while typing, and puts the text in line on blur", async () => {
      host.workers.setValue(16);
      await settle();
      type("99");
      await settle();
      expect(host.workers.value).toBe(16);
      expect(input().value).toBe("99");
      input().dispatchEvent(new Event("blur"));
      await settle();
      expect(input().value).toBe("16");
      expect(host.workers.value).toBe(16);
    });

    it("raises a value below min to min on blur", async () => {
      type("0");
      await settle();
      expect(input().value).toBe("0");
      input().dispatchEvent(new Event("blur"));
      await settle();
      expect(host.workers.value).toBe(1);
      expect(input().value).toBe("1");
    });

    it("writes null as min", async () => {
      host.workers.setValue(null as unknown as number);
      await settle();
      expect(input().value).toBe("1");
    });

    it("keeps an emptied field empty until blur, then returns to min", async () => {
      type("");
      await settle();
      expect(input().value).toBe("");
      expect(host.workers.value).toBe(4);
      input().dispatchEvent(new Event("blur"));
      await settle();
      expect(host.workers.value).toBe(1);
      expect(input().value).toBe("1");
    });

    it("drops anything that is not a digit", async () => {
      type("1a2");
      await settle();
      expect(input().value).toBe("12");
      expect(host.workers.value).toBe(12);
    });
  });

  describe("KoField", () => {
    it("renders the error with role alert and links it to the control", async () => {
      host.error.set("Too many workers");
      await settle();
      const alert = root().querySelector<HTMLElement>('[role="alert"]')!;
      expect(alert.textContent).toContain("Too many workers");
      expect(input().getAttribute("aria-describedby")).toBe(alert.id);
      expect(input().getAttribute("aria-invalid")).toBe("true");
    });

    it("points the control at the hint when there is no error, and back again", async () => {
      const hintId = input().getAttribute("aria-describedby")!;
      expect(root().querySelector("#" + hintId)!.textContent).toContain("How many.");
      expect(input().hasAttribute("aria-invalid")).toBe(false);
      host.error.set("Bad");
      await settle();
      host.error.set(undefined);
      await settle();
      expect(input().hasAttribute("aria-invalid")).toBe(false);
      expect(input().getAttribute("aria-describedby")).toBe(hintId);
    });

    it("links a plain input to its hint", () => {
      const name = root().querySelector<HTMLInputElement>("#name")!;
      expect(name.getAttribute("aria-describedby")).toMatch(/^ko-field-message-\d+$/);
    });
  });

  describe("KoDisclosure", () => {
    const toggle = () => root().querySelector<HTMLButtonElement>("ko-disclosure button")!;

    it("is closed by default and toggles", async () => {
      expect(root().querySelector("#advanced")).toBeNull();
      toggle().click();
      await settle();
      expect(toggle().getAttribute("aria-expanded")).toBe("true");
      expect(root().querySelector("#advanced")).not.toBeNull();
      toggle().click();
      await settle();
      expect(root().querySelector("#advanced")).toBeNull();
    });

    it("cannot be closed while forceOpen is set", async () => {
      host.force.set(true);
      await settle();
      expect(toggle().getAttribute("aria-expanded")).toBe("true");
      toggle().click();
      await settle();
      expect(toggle().getAttribute("aria-expanded")).toBe("true");
      expect(root().querySelector("#advanced")).not.toBeNull();
    });
  });
});
